create or replace function public.manhunt_next(c jsonb)
returns jsonb language plpgsql volatile set search_path = '' as $$
declare r float8:=greatest(0,(c->>'radius')::float8*.72-5);
 goals jsonb:='[{"lat":38.9945,"lng":-76.9436},{"lat":38.993,"lng":-76.947},{"lat":38.989,"lng":-76.943},{"lat":38.988,"lng":-76.947},{"lat":38.9855,"lng":-76.9425},{"lat":38.9835,"lng":-76.9445}]';
 target jsonb:=c->'target'; candidate jsonb; d float8; shift float8;
 a float8:=radians((c->>'lat')::float8); b float8; dl float8; bearing float8; step float8; lat float8; lng float8;
begin
 if target is null or target='null'::jsonb then
  select x into target from jsonb_array_elements(goals) x
   where public.manhunt_distance(c,x)<=(c->>'radius')::float8*.92 and public.manhunt_on_campus(x)
   order by random() limit 1;
  target:=coalesce(target,jsonb_build_object('lat',c->'lat','lng',c->'lng'));
 end if;
 d:=public.manhunt_distance(c,target);
 shift:=least(d,greatest(d-r,((c->>'radius')::float8-r)*(.7+.28*random())));
 b:=radians((target->>'lat')::float8);dl:=radians((target->>'lng')::float8-(c->>'lng')::float8);
 bearing:=atan2(sin(dl)*cos(b),cos(a)*sin(b)-sin(a)*cos(b)*cos(dl));step:=shift/6371000;
 lat:=asin(sin(a)*cos(step)+cos(a)*sin(step)*cos(bearing));
 lng:=radians((c->>'lng')::float8)+atan2(sin(bearing)*sin(step)*cos(a),cos(step)-sin(a)*sin(lat));
 candidate:=jsonb_build_object('radius',r,'lat',degrees(lat),'lng',degrees(lng),'target',target);
 if public.manhunt_on_campus(candidate) then return candidate;end if;
 return c||jsonb_build_object('radius',r,'target',jsonb_build_object('lat',c->'lat','lng',c->'lng'));
end;
