create or replace function public.manhunt_powerup(c jsonb, round_number integer, spawned double precision)
returns jsonb language plpgsql volatile set search_path = '' as $$
declare candidate jsonb;
begin
 -- Same bundled sidewalk samples as the browser demo. No off-path fallback.
 select jsonb_build_object('lat',point->0,'lng',point->1) into candidate
 from jsonb_array_elements(public.manhunt_path_points()) as points(point)
 where public.manhunt_distance(c,jsonb_build_object('lat',point->0,'lng',point->1))<=greatest(0,(c->>'radius')::float8-20)
 order by random() limit 1;
 if candidate is null then return null;end if;
 return candidate||jsonb_build_object('id',gen_random_uuid(),'radius',20,'round',round_number,'spawned_at',spawned);
end;
$$;

-- Conservative GPS estimates. Only the current anchor is retained, never a route.
create or replace function public.manhunt_track(p jsonb, fix jsonb, t float8)
returns jsonb language plpgsql immutable set search_path='' as $$
declare a jsonb:=p->'stats_anchor'; st jsonb:=coalesce(p->'stats','{"distance_m":0,"top_mps":0,"collected":0,"used":0}'::jsonb);
 dt float8; d float8; sample_time float8:=coalesce((fix->>'captured_at')::float8,t);
begin
 if sample_time>t+1 or sample_time<t-15 or coalesce((fix->>'accuracy')::float8,999)>20 then return p;end if;
 if a is not null and a<>'null'::jsonb then
  dt:=sample_time-(a->>'time')::float8;
  if dt<=0 then return p;end if;
  if dt<5 then return p;end if;
  if dt<=20 then
   d:=public.manhunt_distance(a,fix);
   if d<greatest(5,((a->>'accuracy')::float8+(fix->>'accuracy')::float8)/2) and dt<20 then return p;end if;
   if d>=greatest(5,((a->>'accuracy')::float8+(fix->>'accuracy')::float8)/2) and d/dt<=12 then
    st:=st||jsonb_build_object('distance_m',coalesce((st->>'distance_m')::float8,0)+d,'top_mps',greatest(coalesce((st->>'top_mps')::float8,0),d/dt));
   end if;
  end if;
 end if;
 return p||jsonb_build_object('stats',st,'stats_anchor',jsonb_build_object('lat',fix->'lat','lng',fix->'lng','accuracy',fix->'accuracy','time',sample_time));
end;
$$;

-- Enter a frozen, three-minute final chase only after hunting begins.
create or replace function public.manhunt_finale(s jsonb, players jsonb, t float8)
returns jsonb language plpgsql volatile set search_path='' as $$
declare runner jsonb; c jsonb:=s->'circle'; candidate jsonb; origin jsonb; attempt int;
begin
 if s->>'phase'<>'active' or s->>'started_at' is null or s->'escape' is not null and s->'escape'<>'null'::jsonb then return jsonb_set(s,'{players}',players);end if;
 if (select count(*) from jsonb_array_elements(players) x where x->>'role'='runner' and not coalesce((x->>'left')::boolean,false))<>1 then return jsonb_set(s,'{players}',players);end if;
 select x into runner from jsonb_array_elements(players) x where x->>'role'='runner' and not coalesce((x->>'left')::boolean,false);
 origin:=case when runner->>'lat' is not null then runner else c end;
 for attempt in 1..2 loop
  select jsonb_build_object('lat',point->0,'lng',point->1) into candidate
  from jsonb_array_elements(public.manhunt_path_points()) points(point)
  where public.manhunt_distance(c,jsonb_build_object('lat',point->0,'lng',point->1))<=greatest(0,(c->>'radius')::float8-20)
   and public.manhunt_distance(origin,jsonb_build_object('lat',point->0,'lng',point->1)) between 60 and 400
  order by random() limit 1;
  if candidate is not null then exit;end if;
  c:=coalesce(s->'last_escape_circle','{"lat":38.9897,"lng":-76.9436,"radius":800}'::jsonb);
 end loop;
 -- Farther points remain preferable to an automatic win underneath the runner.
 if candidate is null then
  select jsonb_build_object('lat',point->0,'lng',point->1) into candidate
  from jsonb_array_elements(public.manhunt_path_points()) points(point)
  where public.manhunt_distance(c,jsonb_build_object('lat',point->0,'lng',point->1))<=greatest(0,(c->>'radius')::float8-20)
  order by public.manhunt_distance(origin,jsonb_build_object('lat',point->0,'lng',point->1)) desc limit 1;
 end if;
 if candidate is null then raise exception 'No sidewalk escape zone available';end if;
 select jsonb_agg(x||'{"pending_until":null,"pending_circle":null}'::jsonb) into players from jsonb_array_elements(players) x;
 return s||jsonb_build_object('players',players,'circle',c,'next',c,'powerup',null,'deadline',t+180,'escape',candidate||jsonb_build_object('radius',20,'runner_id',runner->>'id','spawned_at',t));
end;
$$;

-- Runners are live for all room members. Hunter GPS remains viewer-specific.
create or replace function public.manhunt_snapshot(s jsonb, t double precision)
returns jsonb language plpgsql stable set search_path = '' as $$
declare viewer jsonb; p jsonb; q jsonb; output jsonb:='[]'; near boolean:=false;
 clear boolean:=true; valid boolean; ready boolean; live boolean;
begin
 select x into viewer from jsonb_array_elements(s->'players') x where x->>'id'=auth.uid()::text;
 valid:=s->>'phase'='active' and viewer->>'role'='runner'
   and viewer->>'lat' is not null and t-(viewer->>'updated')::float8<=15
   and (viewer->>'accuracy')::float8<=30;
 for p in select x from jsonb_array_elements(s->'players') x loop
  if p->>'role'='hunter' and not coalesce((p->>'left')::boolean,false) then
   if p->>'lat' is null or coalesce(t-(p->>'updated')::float8,999)>15 or coalesce((p->>'accuracy')::float8,999)>30 then clear:=false;
   else
    if valid and public.manhunt_distance(viewer,p)<=30 then near:=true;end if;
    if valid and public.manhunt_distance(viewer,p)<=40 then clear:=false;end if;
   end if;
  end if;
  ready:=p->>'lat' is not null and coalesce(t-(p->>'updated')::float8,999)<=30
    and coalesce((p->>'accuracy')::float8,999)<=100
    and public.manhunt_distance(p,s->'circle')<=(s->'circle'->>'radius')::float8+20;
  live:=p->>'role'='runner' or p->>'id'=auth.uid()::text or (p->>'role'='hunter' and (viewer->>'role'='hunter' or (s->>'phase'='active' and viewer->>'role'='runner' and coalesce((viewer->>'reveal_until')::float8,0)>t)));
  q:=(p-'ping'-'stats_anchor')||jsonb_build_object('ready',ready,'location_kind',case when live then 'live' else 'hidden' end);
  if p->>'id'<>auth.uid()::text then q:=q-'powerups'-'reveal_until'-'stats';end if;
  if not live then
   q:=q||jsonb_build_object('lat',null,'lng',null,'accuracy',null,'updated',null);
  end if;
  if s->>'phase'='finished' or coalesce((p->>'left')::boolean,false) then
   q:=q||'{"lat":null,"lng":null,"accuracy":null,"updated":null}'::jsonb;
  end if;
  output:=output||jsonb_build_array(q);
 end loop;
 return jsonb_set(jsonb_set(jsonb_set(s-'kicked_ids'-'last_escape_circle','{players}',output),'{circle}',(s->'circle')-'target'),'{next}',(s->'next')-'target')||jsonb_build_object('server_now',t,
   'hunter_nearby',case when valid then near else null end,
   'hunters_clear',valid and clear);
end;
$$;

create or replace function public.manhunt_enter(p_name text,p_code text default null)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare u uuid:=auth.uid(); t float8:=extract(epoch from clock_timestamp());
 r public.manhunt_rooms%rowtype; s jsonb; p jsonb; c text;
 campus jsonb:='{"lat":38.9897,"lng":-76.9436,"radius":800}';
begin
 if u is null then raise exception 'Sign in anonymously first'; end if;
 if p_name is null or length(trim(p_name)) not between 1 and 24 then raise exception 'Name must be 1–24 characters';end if;
 if p_code is null then
   if (select count(*) from public.manhunt_rooms where host=u and expires_at>now() and state->>'phase'<>'finished')>=3 then raise exception 'You already host three rooms. End an existing game first';end if;
   loop
     c:=upper(substr(replace(gen_random_uuid()::text,'-',''),1,6));
     s:=jsonb_build_object('code',c,'host',u,'phase','lobby','round',0,'deadline',null,'circle',campus,'next',public.manhunt_next(campus),'players',jsonb_build_array(jsonb_build_object('id',u,'name',trim(p_name),'role','runner','lat',null,'lng',null,'updated',null)));
     begin insert into public.manhunt_rooms(code,host,state) values(c,u,s);exit;exception when unique_violation then end;
   end loop;
 else
   c:=upper(trim(p_code));
   select * into r from public.manhunt_rooms where code=c and expires_at>now() for update;
   if not found then raise exception 'Room not found or expired';end if;
   s:=r.state;
   if coalesce(s->'kicked_ids','[]'::jsonb) ? u::text then raise exception 'You were removed from this lobby.';end if;
   if exists(select 1 from jsonb_array_elements(s->'players') x where x->>'id'=u::text and not coalesce((x->>'left')::boolean,false)) then
     return public.manhunt_snapshot(s,t);
   end if;
   if s->>'phase'<>'lobby' then raise exception 'This game has already started or ended';end if;
   if jsonb_array_length(s->'players')>=15 then raise exception 'This room is full (15 players)';end if;
   p:=jsonb_build_object('id',u,'name',trim(p_name),'role','runner','lat',null,'lng',null,'updated',null);
   s:=jsonb_set(s,'{players}',(s->'players')||jsonb_build_array(p));
   update public.manhunt_rooms set state=s where code=c;
 end if;
 return public.manhunt_snapshot(s,t);
end;
$$;

create or replace function public.manhunt_action(p_code text,p_action text default 'poll',p_payload jsonb default '{}')
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
 u uuid:=auth.uid(); t float8:=extract(epoch from clock_timestamp());
 r public.manhunt_rooms%rowtype; s jsonb; players jsonb; p jsonb; c jsonb;
 n integer; i integer; idx integer:=-1; target_idx integer; h integer; chosen text[];
 deadline float8; pending float8; lat float8; lng float8; accuracy float8;
 campus jsonb:='{"lat":38.9897,"lng":-76.9436,"radius":800}';
begin
 if u is null then raise exception 'Sign in anonymously first';end if;
 if p_action is null or p_action not in ('poll','start','tag','end','leave','reveal','kick') then raise exception 'Unknown game action';end if;
 select * into r from public.manhunt_rooms where code=upper(trim(p_code)) for update;
 if not found then raise exception 'Room not found';end if;
 s:=r.state;players:=s->'players';n:=jsonb_array_length(players);
 for i in 0..n-1 loop
   if players->i->>'id'=u::text and not coalesce((players->i->>'left')::boolean,false) then idx:=i;exit;end if;
 end loop;
 if idx=-1 then
  if coalesce(s->'kicked_ids','[]'::jsonb) ? u::text then raise exception 'You were removed from this lobby.';end if;
  raise exception 'You are not a member of this room';
 end if;
 if r.expires_at<=now() then s:=s||'{"phase":"finished","deadline":null,"end_reason":"Room expired after 12 hours."}'::jsonb;end if;

 -- Resolve an existing finale before accepting late GPS or a tag.
 if s->>'phase'='active' and s->'escape' is not null and s->'escape'<>'null'::jsonb and (s->>'deadline')::float8<=t then
  s:=s||jsonb_build_object('phase','finished','winner','hunters','deadline',null,'ended_at',(s->>'deadline')::float8,'end_reason','Hunters win! The escape timer ran out.');
 end if;
 if s->>'phase'='active' and (s->'escape' is null or s->'escape'='null'::jsonb) then
  s:=public.manhunt_finale(s,players,t);players:=s->'players';
 end if;
 -- Advance against server deadlines BEFORE accepting a new GPS sample.
 -- Late samples cannot rewrite where someone was at an earlier boundary.
 while s->>'phase' in ('headstart','active') and (s->'escape' is null or s->'escape'='null'::jsonb) and (s->>'deadline')::float8<=t loop
   deadline:=(s->>'deadline')::float8;
   if s->>'phase'='headstart' then
     s:=s||jsonb_build_object('phase','active','round',1,'deadline',deadline+300);
   else
     c:=s->'next';
     s:=s||jsonb_build_object('circle',c,'next',public.manhunt_next(c),'round',(s->>'round')::int+1,'deadline',deadline+300,'powerup',public.manhunt_powerup(c,(s->>'round')::int+1,deadline));
     for i in 0..n-1 loop
       p:=players->i;
       if p->>'role'='runner' and not coalesce((p->>'left')::boolean,false) then
         if p->>'pending_until' is not null and (p->>'pending_until')::float8<=deadline then
           p:=p||jsonb_build_object('caught_at',(p->>'pending_until')::float8)||'{"role":"hunter","reason":"Location disconnected","pending_until":null,"pending_circle":null}'::jsonb;
         elsif p->>'lat' is not null and p->>'updated' is not null
           and deadline-(p->>'updated')::float8 between 0 and 30
           and coalesce((p->>'accuracy')::float8,9999)<=100 then
           if public.manhunt_distance(p,c)>(c->>'radius')::float8+20 then
             p:=p||jsonb_build_object('caught_at',deadline)||'{"role":"hunter","reason":"Outside the circle"}'::jsonb;
           end if;
         else
           p:=p||jsonb_build_object('pending_until',deadline+90,'pending_circle',c);
         end if;
         players:=jsonb_set(players,array[i::text],p);
       end if;
     end loop;
   end if;
   if coalesce((s->'circle'->>'radius')::float8,0)>=150 then s:=s||jsonb_build_object('last_escape_circle',s->'circle');end if;
   s:=public.manhunt_finale(s,players,deadline);players:=s->'players';
 end loop;
 -- A delayed poll can cross the entire finale deadline.
 if s->>'phase'='active' and s->'escape' is not null and s->'escape'<>'null'::jsonb and (s->>'deadline')::float8<=t then
  s:=s||jsonb_build_object('phase','finished','winner','hunters','deadline',null,'ended_at',(s->>'deadline')::float8,'end_reason','Hunters win! The escape timer ran out.');
 end if;

 -- Expire grace periods even if no new location arrived.
 for i in 0..n-1 loop
   p:=players->i;
   if p->>'role'='runner' and p->>'pending_until' is not null and t>=(p->>'pending_until')::float8 then
     players:=jsonb_set(players,array[i::text],p||jsonb_build_object('caught_at',(p->>'pending_until')::float8)||'{"role":"hunter","reason":"Location disconnected","pending_until":null,"pending_circle":null}'::jsonb);
   end if;
 end loop;

 if s->>'phase'<>'finished' and p_payload ? 'lat' then
   lat:=(p_payload->>'lat')::float8;lng:=(p_payload->>'lng')::float8;accuracy:=(p_payload->>'accuracy')::float8;
   if lat is null or lng is null or accuracy is null or not(lat between -90 and 90) or not(lng between -180 and 180) or not(accuracy between 0 and 10000) then raise exception 'Invalid GPS sample';end if;
   p:=players->idx;
   if s->>'phase' in ('headstart','active') and s->>'started_at' is not null then p:=public.manhunt_track(p,p_payload,t);end if;
   p:=p||jsonb_build_object('lat',lat,'lng',lng,'accuracy',accuracy,'updated',t);
   if p->>'role'='runner' and p->>'pending_until' is not null and accuracy<=100 then
     if public.manhunt_distance(p,p->'pending_circle')>(p->'pending_circle'->>'radius')::float8+20 then p:=p||'{"role":"hunter","reason":"Outside the circle"}'::jsonb;end if;
     p:=p||'{"pending_until":null,"pending_circle":null}'::jsonb;
   end if;
   players:=jsonb_set(players,array[idx::text],p);
 end if;

 if p_action='kick' then
   if u<>r.host then raise exception 'Only the host can remove players';end if;
   if s->>'phase'<>'lobby' then raise exception 'Players can only be removed from the waiting lobby';end if;
   if p_payload->>'player_id'=u::text then raise exception 'The host cannot kick themselves';end if;
   target_idx:=null;
   for i in 0..n-1 loop
    if players->i->>'id'=p_payload->>'player_id' then target_idx:=i;exit;end if;
   end loop;
   if target_idx is null then raise exception 'Player is not in this lobby';end if;
   s:=s||jsonb_build_object('kicked_ids',coalesce(s->'kicked_ids','[]'::jsonb)||jsonb_build_array(p_payload->>'player_id'));
   players:=players-target_idx;
   if target_idx<idx then idx:=idx-1;end if;
   n:=n-1;
 elsif p_action='start' then
   if u<>r.host then raise exception 'Only the host can start';end if;
   if s->>'phase'<>'lobby' then raise exception 'Game already started';end if;
   h:=(p_payload->>'hunters')::int;
   if n<2 or h is null or h<1 or h>=n then raise exception 'Choose between 1 and player count minus 1 hunters';end if;
   for i in 0..n-1 loop
     p:=players->i;
     if p->>'lat' is null or p->>'updated' is null or t-(p->>'updated')::float8>30 or coalesce((p->>'accuracy')::float8,9999)>100 then raise exception 'Everyone needs a fresh GPS fix (within 100 m accuracy)';end if;
     if public.manhunt_distance(p,campus)>820 then raise exception 'Everyone must be inside the starting circle';end if;
   end loop;
   if coalesce(p_payload->>'selection','random') not in ('random','manual') then raise exception 'Invalid hunter selection mode';end if;
   if p_payload->>'selection'='manual' then
    if jsonb_typeof(p_payload->'hunter_ids') is distinct from 'array' then raise exception 'Choose your hunters';end if;
    select array_agg(value) into chosen from jsonb_array_elements_text(p_payload->'hunter_ids');
    if coalesce(cardinality(chosen),0)<>h or (select count(distinct x) from unnest(chosen) x)<>h then raise exception 'Select exactly % different hunters',h;end if;
    if exists(select 1 from unnest(chosen) x where not exists(select 1 from jsonb_array_elements(players) candidate_player where candidate_player->>'id'=x and not coalesce((candidate_player->>'left')::boolean,false))) then raise exception 'Selected hunter is not in this lobby';end if;
   else
    select array_agg(x->>'id') into chosen from (select x from jsonb_array_elements(players) x order by random() limit h) shuffled;
   end if;
   for i in 0..n-1 loop
     if players->i->>'id'=any(chosen) then players:=jsonb_set(players,array[i::text,'role'],'"hunter"');end if;
   end loop;
   for i in 0..n-1 loop
    p:=(players->i)||jsonb_build_object('initial_hunter',players->i->>'role'='hunter','stats',jsonb_build_object('distance_m',0,'top_mps',0,'collected',0,'used',0),'stats_anchor',null);
    players:=jsonb_set(players,array[i::text],p||jsonb_build_object('ping',null));
   end loop;
   s:=s||jsonb_build_object('phase','headstart','round',0,'deadline',t+300,'started_at',t,'last_escape_circle',campus);
 elsif p_action='tag' then
   if s->>'phase' not in ('headstart','active') then raise exception 'No active game';end if;
   players:=jsonb_set(players,array[idx::text],(players->idx)||case when players->idx->>'role'='runner' then jsonb_build_object('caught_at',t) else '{}'::jsonb end||'{"role":"hunter","reason":"Tagged","pending_until":null,"pending_circle":null}'::jsonb);
 elsif p_action='reveal' then
   p:=players->idx;
   if s->>'phase'<>'active' or p->>'role'<>'runner' then raise exception 'Only active runners can reveal hunters';end if;
   if coalesce((p->>'powerups')::int,0)<1 then raise exception 'No reveal power-ups in your inventory';end if;
   p:=jsonb_set(p,'{stats}',coalesce(p->'stats','{}'::jsonb)||jsonb_build_object('used',coalesce((p->'stats'->>'used')::int,0)+1));
   p:=p||jsonb_build_object('powerups',(p->>'powerups')::int-1,'reveal_until',greatest(t,coalesce((p->>'reveal_until')::float8,0))+60);
   players:=jsonb_set(players,array[idx::text],p);
 elsif p_action='end' then
   if u<>r.host then raise exception 'Only the host can end the game';end if;
   if s->>'phase'<>'finished' then s:=s||'{"phase":"finished","deadline":null,"end_reason":"The host ended the game."}'::jsonb;end if;
 elsif p_action='leave' and s->>'phase'<>'finished' then
   if u=r.host then
     if s->>'phase'<>'finished' then s:=s||'{"phase":"finished","deadline":null,"end_reason":"The host left the room."}'::jsonb;end if;
   elsif s->>'phase'='lobby' then players:=players-idx;
   else players:=jsonb_set(players,array[idx::text],(players->idx)||'{"left":true,"ping":null,"role":"hunter","reason":"Left game","lat":null,"lng":null,"updated":null,"pending_until":null,"pending_circle":null}'::jsonb);
   end if;
 end if;
 -- Only the caller's new, accurate GPS sample can automatically collect.
 -- Never award using another player's old fix or a location predating this spawn.
 p:=case when idx<jsonb_array_length(players) then players->idx else null end;
 if p_action='poll' and p_payload ? 'lat' and s->>'phase'='active'
  and s->'powerup' is not null and s->'powerup'<>'null'::jsonb
  and p->>'role'='runner' and not coalesce((p->>'left')::boolean,false)
  and coalesce((p->>'accuracy')::float8,999)<=30
  and t-(p->>'updated')::float8 between 0 and 15
  and (p->>'updated')::float8>=(s->'powerup'->>'spawned_at')::float8
  and public.manhunt_distance(p,s->'powerup')<=20 then
   players:=jsonb_set(players,array[idx::text],p||jsonb_build_object('powerups',coalesce((p->>'powerups')::int,0)+1,'stats',coalesce(p->'stats','{}'::jsonb)||jsonb_build_object('collected',coalesce((p->'stats'->>'collected')::int,0)+1)));
   s:=s||'{"powerup":null}'::jsonb;
 end if;
 if s->>'started_at' is not null then
 for i in 0..jsonb_array_length(players)-1 loop
  p:=players->i;
  if p->>'role'='hunter' and not coalesce((p->>'initial_hunter')::boolean,false) and p->>'caught_at' is null and not coalesce((p->>'left')::boolean,false) then
   players:=jsonb_set(players,array[i::text],p||jsonb_build_object('caught_at',t));
  elsif coalesce((p->>'left')::boolean,false) and p->>'left_at' is null then
   players:=jsonb_set(players,array[i::text],p||jsonb_build_object('left_at',t));
  end if;
 end loop;
 end if;
 -- Getting caught forfeits unused items and ends an active reveal.
 for i in 0..jsonb_array_length(players)-1 loop
  if players->i->>'role'='hunter' then
   players:=jsonb_set(players,array[i::text],(players->i)||'{"powerups":0,"reveal_until":null}'::jsonb);
  end if;
 end loop;
 if s->>'phase'='active' then
  s:=public.manhunt_finale(s,players,t);players:=s->'players';
 end if;
 -- Only a new accurate fix from the last runner can win, never a cached fix.
 p:=case when idx<jsonb_array_length(players) then players->idx else null end;
 if s->>'phase'='active' and s->'escape' is not null and s->'escape'<>'null'::jsonb
  and p_action='poll' and p_payload ? 'lat' and p->>'id'=s->'escape'->>'runner_id' and p->>'role'='runner'
  and coalesce((p_payload->>'captured_at')::float8,t)>=(s->'escape'->>'spawned_at')::float8
  and coalesce((p_payload->>'captured_at')::float8,t) between t-15 and t+1
  and (p->>'accuracy')::float8<=20 and public.manhunt_distance(p,s->'escape')<=20 then
  s:=s||jsonb_build_object('phase','finished','winner','runner','winner_id',p->>'id','deadline',null,'ended_at',t,'end_reason',(p->>'name')||' escaped! Runner wins.');
 end if;
 if s->>'phase' in ('headstart','active') and not exists(select 1 from jsonb_array_elements(players) x where x->>'role'='runner' and not coalesce((x->>'left')::boolean,false)) then
   s:=s||'{"phase":"finished","deadline":null,"winner":"hunters","end_reason":"Hunters win! Everyone was infected."}'::jsonb;
 end if;
 if s->>'phase'='finished' then
   s:=s||jsonb_build_object('powerup',null,'ended_at',coalesce((s->>'ended_at')::float8,t));
   select coalesce(jsonb_agg(x||'{"lat":null,"lng":null,"accuracy":null,"updated":null,"ping":null,"pending_until":null,"pending_circle":null,"powerups":0,"reveal_until":null,"stats_anchor":null}'::jsonb),'[]') into players from jsonb_array_elements(players) x;
 end if;
 s:=jsonb_set(s,'{players}',players);
 update public.manhunt_rooms set state=s where code=r.code;
 return public.manhunt_snapshot(s,t);
end;
$$;
revoke all on function public.manhunt_finale(jsonb,jsonb,float8) from public, anon, authenticated;
revoke all on function public.manhunt_path_points() from public, anon, authenticated;
revoke all on function public.manhunt_powerup(jsonb,integer,double precision) from public, anon, authenticated;
revoke all on function public.manhunt_snapshot(jsonb,double precision) from public, anon, authenticated;
revoke all on function public.manhunt_distance(jsonb,jsonb) from public, anon, authenticated;
revoke all on function public.manhunt_on_campus(jsonb) from public, anon, authenticated;
revoke all on function public.manhunt_next(jsonb) from public, anon, authenticated;
revoke all on function public.manhunt_enter(text,text) from public, anon;
revoke all on function public.manhunt_action(text,text,jsonb) from public, anon;
grant execute on function public.manhunt_enter(text,text) to authenticated;
grant execute on function public.manhunt_action(text,text,jsonb) to authenticated;
revoke all on function public.manhunt_track(jsonb,jsonb,float8) from public, anon, authenticated;
commit;

